def current_package_family_name() -> str | None:
    """The MSIX package family this process runs from, or None without
    package identity (run from source, or as a plain exe). Kept for the
    Microsoft Store purchase check, which can only ask with identity."""
    try:
        import ctypes

        kernel32 = ctypes.windll.kernel32
        length = ctypes.c_uint32(0)
        # ERROR_INSUFFICIENT_BUFFER (122): there is a name to fetch;
        # APPMODEL_ERROR_NO_PACKAGE (15700): there is none.
        if kernel32.GetCurrentPackageFamilyName(ctypes.byref(length), None) != 122:
            return None
        buffer = ctypes.create_unicode_buffer(length.value)
        if kernel32.GetCurrentPackageFamilyName(ctypes.byref(length), buffer) != 0:
            return None
        return buffer.value or None
    except Exception:
        return None


class LicenseState:
    """Whether this copy is in its free trial, in limited mode or premium.

    The trial clock starts at the first start and lives in settings.json
    ("trial_started", "trial_last_seen"). It never runs backwards: the latest
    time pdfNote has seen is what counts, so turning the system clock back
    adds no days. A purchase (premium) will come from the Microsoft Store.

    Nothing in the shipped program can force a mode: forced_mode is set
    only by the tests and by tools that drive a window (store/make_shots.py).
    The environment variable of 5.25-5.37 and the source constant of 5.38
    are gone -- the first let an unmodified build from the published source
    stay premium, and the second was a second switch that a release could
    ship with by mistake.
    """

    TRIAL = "trial"
    LIMITED = "limited"
    PREMIUM = "premium"
    _shared: dict[bool, "LicenseState"] = {}

    def __init__(
        self,
        settings: RecentFiles,
        *,
        test_mode: bool = False,
        clock: Callable[[], datetime] | None = None,
    ) -> None:
        self.settings = settings
        self.test_mode = test_mode
        self.clock = clock or (lambda: datetime.now(timezone.utc))
        # A mode set by the tests; None works it out. The test suite runs
        # premium unless a check asks for another mode.
        self.forced_mode: str | None = self.PREMIUM if test_mode else None
        self.purchased = False
        self.mode = self.TRIAL
        self.days_left = TRIAL_DAYS
        self.refresh()

    @classmethod
    def shared(cls, settings: RecentFiles, test_mode: bool = False) -> "LicenseState":
        """One state per process (one more for test windows), so every
        pdfNote window -- a tab dragged out makes another -- agrees."""
        state = cls._shared.get(test_mode)
        if state is None:
            state = cls._shared[test_mode] = cls(settings, test_mode=test_mode)
        return state

    @staticmethod
    def _read_time(value: Any) -> datetime | None:
        try:
            parsed = datetime.fromisoformat(str(value))
        except (TypeError, ValueError):
            return None
        return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=timezone.utc)

    def trial_days_left(self) -> int:
        data = self.settings.data
        now = self.clock()
        started = self._read_time(data.get("trial_started"))
        last_seen = self._read_time(data.get("trial_last_seen"))
        changed = False
        if started is None:
            started = now
            data["trial_started"] = started.isoformat()
            changed = True
        latest = max(moment for moment in (now, last_seen, started) if moment is not None)
        # Written at most hourly: this runs on every check.
        if last_seen is None or latest - last_seen >= timedelta(hours=1):
            data["trial_last_seen"] = latest.isoformat()
            changed = True
        if changed:
            self.settings.save()
        used = (latest - started).total_seconds() / 86400
        return max(0, TRIAL_DAYS - math.floor(used))

    def refresh(self) -> str:
        forced = self.forced_mode
        if forced is not None:
            self.mode = forced
            self.days_left = max(1, self.trial_days_left()) if forced == self.TRIAL else 0
        elif self.purchased:
            self.mode = self.PREMIUM
            self.days_left = 0
        else:
            self.days_left = self.trial_days_left()
            self.mode = self.TRIAL if self.days_left > 0 else self.LIMITED
        return self.mode

    @property
    def limited(self) -> bool:
        return self.mode == self.LIMITED

    @property
    def marks_visible(self) -> bool:
        """The premium mark shows in limited mode only (v5.28).

        During the trial every command works, so marking one says nothing
        useful -- only that it will be taken away, while the person is still
        deciding. After a purchase there is nothing to mark. The mark exists
        to explain why something is refused, which happens in limited mode
        and nowhere else. The trial itself is still shown: the status bar
        counts the days down, and the Store listing states the terms.
        """
        return self.mode == self.LIMITED


def premium_menu_blocked(widget: QWidget) -> bool:
    """For a widget that opens its own right-click menu: does its pdfNote
    window hold the menu back (limited mode), after saying so?"""
    window = widget.window()
    blocked = getattr(window, "_premium_blocked", None)
    return bool(blocked is not None and blocked(window.PREMIUM_CONTEXT_MENU))


# ---- Microsoft Store: the premium purchases ---------------------------------
#
# The premium features are sold as add-ons of the Microsoft Store edition: a
# one-time purchase and a subscription. Every durable
# add-on pdfNote has is one of them, so any of them, active, makes this copy
# premium. Only the packaged Store edition can ask the Store; a build from the
# source has no package identity and keeps the free trial and limited mode.
#
# Every Store call runs on StoreClient's thread. Some show Microsoft's own
# purchase window and last as long as the customer takes; none may hold up
# the UI thread, which goes on drawing pdfNote meanwhile.

STORE_PRODUCT_KINDS = ["Durable"]
# The PyWinRT modules the Store code imports, directly or through the ones it
# names. pdfNote.spec bundles the same list. PyInstaller only warns when one is
# missing, and 5.40 was built that way: an exe that could never sell. The
# self-test imports each of them, so such a build now fails it.
STORE_WINRT_MODULES = (
    "winrt.runtime", "winrt.runtime.interop", "winrt.system",
    "winrt.windows.foundation", "winrt.windows.foundation.collections",
    "winrt.windows.services.store",
)
# StoreDurationUnit, as the Store numbers it.
STORE_PERIOD_UNITS = {0: "minute", 1: "hour", 2: "day", 3: "week", 4: "month", 5: "year"}


@dataclass(frozen=True)
class StoreOffer:
    """One add-on as the Store offers it to this customer, priced in their
    currency and formatted by the Store."""

    store_id: str
    title: str
    price: str
    subscription: bool = False
    period: int = 0
    period_unit: str = ""


class StorePurchase:
    """What became of a purchase request (the Store's StorePurchaseStatus,
    and FAILED for an error before it could answer)."""

    SUCCEEDED = "succeeded"
    ALREADY_OWNED = "already_owned"
    CANCELLED = "cancelled"
    NETWORK_ERROR = "network_error"
    SERVER_ERROR = "server_error"
    FAILED = "failed"
    BY_STATUS = {0: SUCCEEDED, 1: ALREADY_OWNED, 2: CANCELLED, 3: NETWORK_ERROR, 4: SERVER_ERROR}


def store_purchase_supported() -> bool:
    """Can this copy buy premium and check it in the Microsoft Store? The
    packaged Store edition can, on Windows with the Store projection
    bundled; nothing else can."""
    if sys.platform != "win32" or current_package_family_name() is None:
        return False
    try:
        import importlib.util

        return importlib.util.find_spec("winrt.windows.services.store") is not None
    except (ImportError, ValueError):
        return False


class WinRTStore:
    """Windows.Services.Store through PyWinRT, made and used on the Store
    thread only. Its calls are coroutines awaited there: a Store operation
    in progress holds neither the UI thread nor Python's lock."""

    def __init__(self, on_licenses_changed: Callable[[], None]) -> None:
        from winrt.runtime import ApartmentType, init_apartment

        try:
            init_apartment(ApartmentType.MULTI_THREADED)
        except OSError:
            pass  # this thread has its apartment already
        self._on_licenses_changed = on_licenses_changed
        self._contexts: dict[int, Any] = {}
        self._change_token: Any = None

    def _context(self, hwnd: int) -> Any:
        """A StoreContext whose windows belong to the pdfNote window `hwnd`.
        A desktop app must name that window, or the Store answers wrongly
        (Microsoft Learn, "Using the StoreContext class with the Desktop
        Bridge")."""
        context = self._contexts.get(hwnd)
        if context is None:
            from winrt.runtime.interop import initialize_with_window
            from winrt.windows.services.store import StoreContext

            context = StoreContext.get_default()
            initialize_with_window(context, hwnd)
            self._contexts[hwnd] = context
            if self._change_token is None:
                self._change_token = context.add_offline_licenses_changed(
                    lambda _sender, _args: self._on_licenses_changed()
                )
        return context

    async def owned(self, hwnd: int) -> bool:
        licence = await self._context(hwnd).get_app_license_async()
        return any(add_on.is_active for add_on in licence.add_on_licenses.values())

    async def offers(self, hwnd: int) -> list[StoreOffer]:
        result = await self._context(hwnd).get_associated_store_products_async(STORE_PRODUCT_KINDS)
        error = int(getattr(result.extended_error, "value", 0) or 0)
        if error:
            raise OSError(error, "the Microsoft Store could not list the add-ons")
        offers: list[StoreOffer] = []
        for product in result.products.values():
            skus = list(product.skus)
            sku = skus[0] if skus else None
            price = sku.price if sku is not None else product.price
            if sku is not None and sku.is_subscription:
                info = sku.subscription_info
                offers.append(StoreOffer(
                    product.store_id, product.title,
                    price.formatted_recurrence_price or price.formatted_price,
                    subscription=True,
                    period=int(info.billing_period),
                    period_unit=STORE_PERIOD_UNITS.get(int(info.billing_period_unit), ""),
                ))
            else:
                offers.append(StoreOffer(product.store_id, product.title, price.formatted_price))
        return sort_store_offers(offers)

    async def purchase(self, hwnd: int, store_id: str) -> str:
        result = await self._context(hwnd).request_purchase_async(store_id)
        return StorePurchase.BY_STATUS.get(int(result.status), StorePurchase.FAILED)


def sort_store_offers(offers: list[StoreOffer]) -> list[StoreOffer]:
    """The one-time purchase first, then subscriptions from the shortest
    period."""
    unit_order = {"minute": 0, "hour": 1, "day": 2, "week": 3, "month": 4, "year": 5}
    return sorted(
        offers,
        key=lambda offer: (
            offer.subscription, unit_order.get(offer.period_unit, 9), offer.period, offer.title,
        ),
    )


class StoreClient(QObject):
    """The way to the Microsoft Store in this process: a thread of its own
    running an event loop, which carries out each request and hands the
    answer back to the UI thread.

    `backend_factory` makes the backend on that thread (WinRTStore, or a
    stand-in in the tests); it is given the function to call when the
    Store says the licences changed."""

    _answered = Signal(object, object)
    _shared: "StoreClient | None" = None
    # Whether this copy can reach the Store is settled once per process.
    _looked: bool = False

    def __init__(self, backend_factory: Callable[[Callable[[], None]], Any]) -> None:
        super().__init__()
        self._factory = backend_factory
        self._backend: Any = None
        self._loop: Any = None
        self._ready = threading.Event()
        # Always queued. A request the Store answers before its done-callback
        # is attached runs that callback at once, on the UI thread, and a
        # direct connection then finished the purchase inside purchase()
        # itself -- before the caller had even seen it start.
        self._answered.connect(self._deliver, Qt.QueuedConnection)
        self.hwnd = 0
        self.purchase_running = False
        # Told True or False whenever the Store answers whether an add-on
        # is owned. An unanswered question tells them nothing.
        self.license_listeners: list[Callable[[bool], None]] = []

    @classmethod
    def shared(cls) -> "StoreClient | None":
        """The Store edition's client; None where there is no Store."""
        if cls._shared is None and not cls._looked:
            cls._looked = True
            if store_purchase_supported():
                cls._shared = cls(WinRTStore)
        return cls._shared

    def _run(self) -> None:
        import asyncio

        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        try:
            self._backend = self._factory(self._licenses_changed)
        except Exception as error:  # answered to every request instead
            self._backend = error
        self._loop = loop
        self._ready.set()
        loop.run_forever()

    def _start(self) -> None:
        if not self._ready.is_set():
            threading.Thread(target=self._run, name="pdfNote Microsoft Store", daemon=True).start()
            self._ready.wait(10)

    def _submit(self, method: str, args: tuple[Any, ...], callback: Callable[[Any], None]) -> None:
        """Run backend.method(*args) on the Store thread. `callback` gets
        the result, or the exception, on the UI thread."""
        import asyncio

        self._start()
        loop = self._loop
        if loop is None:
            callback(RuntimeError("the Microsoft Store thread did not start"))
            return

        async def call() -> Any:
            backend = self._backend
            if isinstance(backend, BaseException):
                raise backend
            return await getattr(backend, method)(*args)

        def done(future: Any) -> None:
            try:
                result = future.result()
            except BaseException as error:  # the answer is the error
                result = error
            self._answered.emit(callback, result)

        asyncio.run_coroutine_threadsafe(call(), loop).add_done_callback(done)

    def _deliver(self, callback: Callable[[Any], None], result: Any) -> None:
        callback(result)

    def _licenses_changed(self) -> None:
        """The Store's own notice, on a thread of its own: ask again, from
        the UI thread."""
        self._answered.emit(lambda _result: self.check_license(), None)

    def check_license(self) -> None:
        """Ask whether an add-on is owned, and tell the listeners."""
        if self.hwnd:
            self._submit("owned", (self.hwnd,), self._license_answered)

    def _license_answered(self, result: Any) -> None:
        # No answer is not "not owned": the Store may be out of reach for a
        # moment. What is known stays (Terms of Use 5.9).
        if isinstance(result, BaseException):
            return
        for listener in list(self.license_listeners):
            listener(bool(result))

    def load_offers(self, hwnd: int, callback: Callable[[Any], None]) -> None:
        self._submit("offers", (hwnd,), callback)

    def purchase(self, hwnd: int, store_id: str, callback: Callable[[Any], None]) -> None:
        """Open Microsoft's purchase window for `store_id`. `callback` gets
        a StorePurchase value, or the exception."""
        self.purchase_running = True

        def finished(result: Any) -> None:
            self.purchase_running = False
            if result in (StorePurchase.SUCCEEDED, StorePurchase.ALREADY_OWNED):
                self.check_license()
            callback(result)

        self._submit("purchase", (hwnd, store_id), finished)


def apply_store_license(owned: bool) -> None:
    """The Store's answer, applied: premium while an add-on is owned. Every
    window shares the one state, and all of them are updated."""
    state = LicenseState._shared.get(False)
    if state is None or state.purchased == owned:
        return
    state.purchased = owned
    state.refresh()
    for window in list(OPEN_WINDOWS):
        if getattr(window, "test_mode", True):
            continue
        try:
            window._apply_license_state()
        except RuntimeError:
            continue


PREMIUM_BADGE_COMPACT_TEXT = "P"


def premium_badge_font(base: QFont) -> QFont:
    font = QFont(base)
    size = base.pointSizeF()
    font.setPointSizeF(max(7.0, size * 0.82) if size > 0 else 7.5)
    font.setBold(True)
    font.setItalic(False)
    return font


def premium_badge_size(base: QFont, compact: bool = False) -> QSize:
    metrics = QFontMetrics(premium_badge_font(base))
    text = PREMIUM_BADGE_COMPACT_TEXT if compact else PREMIUM_BADGE_TEXT
    height = metrics.height() + 2
    width = metrics.horizontalAdvance(text) + (8 if compact else 12)
    return QSize(max(width, height if compact else width), height)


def draw_premium_badge(
    painter: QPainter, rect: QRect, base: QFont, compact: bool = False
) -> None:
    """A rounded rectangle in the premium colour reading "Premium" -- or just
    "P" where there is no room for the word (a 22px icon, a key tip)."""
    painter.save()
    painter.setRenderHint(QPainter.Antialiasing, True)
    painter.setPen(Qt.NoPen)
    painter.setBrush(QColor(PREMIUM_BADGE_BACKGROUND))
    radius = rect.height() * 0.34
    painter.drawRoundedRect(QRectF(rect), radius, radius)
    painter.setPen(QColor(PREMIUM_BADGE_FOREGROUND))
    painter.setFont(premium_badge_font(base))
    # The badge always reads left to right, in Arabic too: it is a name.
    painter.drawText(
        rect, Qt.AlignCenter,
        PREMIUM_BADGE_COMPACT_TEXT if compact else PREMIUM_BADGE_TEXT,
    )
    painter.restore()


def premium_compact_badge(side: float) -> QPixmap:
    """The "P" badge at a given size, drawn without a widget's font: the
    icons it goes on are painted on their own grid."""
    size = max(9, int(round(side)))
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)
    font = QFont("Segoe UI")
    font.setPixelSize(max(7, int(size * 0.72)))
    font.setBold(True)
    painter = QPainter(pixmap)
    try:
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setPen(QPen(QColor("#1E1F23"), max(1.0, size * 0.07)))
        painter.setBrush(QColor(PREMIUM_BADGE_BACKGROUND))
        radius = size * 0.22
        painter.drawRoundedRect(QRectF(0.6, 0.6, size - 1.2, size - 1.2), radius, radius)
        painter.setPen(QColor(PREMIUM_BADGE_FOREGROUND))
        painter.setFont(font)
        painter.drawText(
            QRect(0, 0, size, size), Qt.AlignCenter, PREMIUM_BADGE_COMPACT_TEXT
        )
    finally:
        painter.end()
    return pixmap


def premium_badge_pixmap(base: QFont, ratio: float = 1.0) -> QPixmap:
    """The badge as a picture, for a label laid over a menu entry."""
    size = premium_badge_size(base)
    pixmap = QPixmap(int(size.width() * ratio), int(size.height() * ratio))
    pixmap.setDevicePixelRatio(ratio)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    try:
        draw_premium_badge(painter, QRect(0, 0, size.width(), size.height()), base)
    finally:
        painter.end()
    return pixmap


def install_premium_badges(menu: QMenu) -> None:
    """Show the badge on every entry of `menu` whose text carries
    PREMIUM_MENU_MARK.

    Not a QProxyStyle: pdfNote's stylesheet sets QMenu::item, so Qt draws
    the entries itself and a style's drawControl is never called for them.
    The badge is a child widget instead, over room the menu reserves by
    widening its own right padding.
    """
    marked = [
        action for action in menu.actions()
        if action.text() and PREMIUM_MENU_MARK in action.text()
    ]
    labels: dict[QAction, QLabel] = getattr(menu, "_pdfnote_badges", {})
    menu._pdfnote_badges = labels  # type: ignore[attr-defined]
    if not marked:
        for label in labels.values():
            label.hide()
        return
    badge = premium_badge_size(menu.font())
    # The room the badge sits in. QMenu::item's own right padding is 30px
    # (see _stylesheet); the badge needs its width on top of that.
    menu.setStyleSheet(
        f"QMenu::item {{ padding-right: {30 + badge.width() + 8}px; }}"
    )

    def place() -> None:
        right_to_left = menu.isRightToLeft()
        for action in menu.actions():
            label = labels.get(action)
            if action not in marked:
                if label is not None:
                    label.hide()
                continue
            rect = menu.actionGeometry(action)
            if not rect.isValid():
                continue
            if label is None:
                label = QLabel(menu)
                label.setAttribute(Qt.WA_TransparentForMouseEvents, True)
                labels[action] = label
            label.setPixmap(premium_badge_pixmap(menu.font(), label.devicePixelRatioF()))
            label.resize(badge)
            left = rect.left() + 8 if right_to_left else rect.right() - badge.width() - 8
            label.move(left, rect.center().y() - badge.height() // 2 + 1)
            label.show()
            label.raise_()

    if not getattr(menu, "_pdfnote_badges_wired", False):
        menu._pdfnote_badges_wired = True  # type: ignore[attr-defined]
        # actionGeometry() is only right once the menu has been laid out.
        menu.aboutToShow.connect(lambda: QTimer.singleShot(0, place))
    place()


def theme_palette() -> QPalette:
    """The colours Qt uses for whatever the stylesheet does not cover.

    A stylesheet cannot reach every part of every control: a spin box's up
    and down arrows, for instance, are drawn by the style, from the
    palette. pdfNote set the style and not the palette, so those parts came
    out in Fusion's own light colours -- on the dark theme, the font size
    box's arrows measured 1.19:1 against the field they sit on, which is to
    say they were not there. Setting this closes the whole class.
    """
    palette = QPalette()
    text = QColor(COLORS["text"])
    field = QColor(COLORS["field"])
    for group in (QPalette.Active, QPalette.Inactive):
        palette.setColor(group, QPalette.Window, QColor(COLORS["chrome"]))
        palette.setColor(group, QPalette.WindowText, text)
        palette.setColor(group, QPalette.Base, field)
        palette.setColor(group, QPalette.AlternateBase, QColor(COLORS["list_alt"]))
        palette.setColor(group, QPalette.Text, text)
        palette.setColor(group, QPalette.Button, QColor(COLORS["toolbar_hover"]))
        palette.setColor(group, QPalette.ButtonText, text)
        palette.setColor(group, QPalette.BrightText, QColor(COLORS["on_accent"]))
        palette.setColor(group, QPalette.Highlight, QColor(COLORS["accent"]))
        palette.setColor(group, QPalette.HighlightedText, QColor(COLORS["on_accent"]))
        palette.setColor(group, QPalette.ToolTipBase, QColor(COLORS["toolbar"]))
        palette.setColor(group, QPalette.ToolTipText, text)
        palette.setColor(group, QPalette.PlaceholderText, QColor(COLORS["muted"]))
        palette.setColor(group, QPalette.Link, QColor(COLORS["link"]))
    disabled = QColor(COLORS["disabled_text"])
    palette.setColor(QPalette.Disabled, QPalette.Text, disabled)
    palette.setColor(QPalette.Disabled, QPalette.ButtonText, disabled)
    palette.setColor(QPalette.Disabled, QPalette.WindowText, disabled)
    return palette


def app_icon_pixmap(side: int, ratio: float = 1.0) -> QPixmap:
    """pdfNote's own icon at `side` points, sharp on a scaled display.

    A QPixmap handed an .ico takes one frame out of it -- not the largest
    -- so drawing the start screen's 76pt icon that way meant stretching a
    small frame. The 512px PNG beside it is the source instead, rendered
    at as many real pixels as the screen will use.
    """
    ratio = max(1.0, float(ratio or 1.0))
    pixels = max(1, round(side * ratio))
    source = QPixmap(resource_path("pdfNote-512.png"))
    if source.isNull():
        source = QPixmap(resource_path("pdfNote.ico"))
    if source.isNull():
        return source
    scaled = source.scaled(pixels, pixels, Qt.KeepAspectRatio, Qt.SmoothTransformation)
    scaled.setDevicePixelRatio(ratio)
    return scaled


_ARROW_FOLDER: str | None = None
_ARROW_FILES: dict[tuple[str, str, int, int], str] = {}


def arrow_image(direction: str, color: str, width: int = 9, height: int = 6) -> str:
    """A triangle, as a file the stylesheet can point at.

    Qt's stylesheet has no way to draw one. The CSS trick -- a box of no
    size, transparent left and right borders, one coloured border -- is a
    triangle in every browser and a **filled rectangle** in Qt: measured,
    and it is what put square buttons on the scroll bars and square
    arrows on the spin boxes. Leaving the rule out instead draws nothing
    at all on a scroll bar, because once a complex control is styled Qt
    stops drawing the parts the stylesheet does not mention.

    So it is drawn here and saved, once per colour and size, in a folder
    belonging to this run. The path comes back with forward slashes,
    which is what a stylesheet url() wants on Windows.
    """
    global _ARROW_FOLDER
    key = (direction, color, width, height)
    made = _ARROW_FILES.get(key)
    if made is not None:
        return made
    if _ARROW_FOLDER is None:
        _ARROW_FOLDER = tempfile.mkdtemp(prefix="pdfNote-arrows-")
        atexit.register(shutil.rmtree, _ARROW_FOLDER, True)
    # Twice the size, drawn smooth and left for Qt to scale down: an
    # arrow this small is all edge, and a hard 9x6 triangle is ragged.
    scale = 4
    image = QImage(width * scale, height * scale, QImage.Format_ARGB32_Premultiplied)
    image.fill(Qt.transparent)
    painter = QPainter(image)
    painter.setRenderHint(QPainter.Antialiasing, True)
    painter.setPen(Qt.NoPen)
    painter.setBrush(QColor(color))
    span, rise = image.width(), image.height()
    if direction == "up":
        points = [QPointF(span / 2, 0), QPointF(span, rise), QPointF(0, rise)]
    elif direction == "down":
        points = [QPointF(0, 0), QPointF(span, 0), QPointF(span / 2, rise)]
    elif direction == "left":
        points = [QPointF(span, 0), QPointF(span, rise), QPointF(0, rise / 2)]
    else:
        points = [QPointF(0, 0), QPointF(span, rise / 2), QPointF(0, rise)]
    painter.drawPolygon(QPolygonF(points))
    painter.end()
    path = Path(_ARROW_FOLDER) / f"{direction}-{color.lstrip('#')}-{width}x{height}.png"
    image.save(str(path), "PNG")
    made = str(path).replace("\\", "/")
    _ARROW_FILES[key] = made
    return made


def app_logo_pixmap(width: int, ratio: float = 1.0) -> QPixmap:
    """The wordmark for the start screen, `width` points wide.

    It has a transparent surround, so the chrome shows through it in
    either theme. The one shipped is drawn for paper -- 78% of it reaches
    4.5:1 against the light chrome, and against the dark one only 29%
    reaches 3:1 -- and no lighter copy is derived from it: every way of
    doing that tore holes in the note behind the N, and artwork is not
    something to guess at. Ship a `pdfNote-logo-dark.png` beside it,
    drawn for a dark background, and the dark theme uses that instead.
    Returns nothing if neither is there; the caller falls back to the
    icon.
    """
    ratio = max(1.0, float(ratio or 1.0))
    name = "pdfNote-logo-dark.png" if COLORS["chrome"] != LIGHT_COLORS["chrome"] else "pdfNote-logo.png"
    source = QPixmap(resource_path(name))
    if source.isNull():
        source = QPixmap(resource_path("pdfNote-logo.png"))
    if source.isNull():
        return source
    scaled = source.scaledToWidth(max(1, round(width * ratio)), Qt.SmoothTransformation)
    scaled.setDevicePixelRatio(ratio)
    return scaled


def app_icon() -> QIcon:
    """Every size Windows may ask for, and one big enough for a 4K taskbar."""
    icon = QIcon(resource_path("pdfNote.ico"))
    large = resource_path("pdfNote-512.png")
    if Path(large).exists():
        icon.addFile(large)
    return icon


def install_application_style(application: QApplication) -> None:
    """The one place the application's style is chosen. Every entry point --
    pdfNote itself and each QA script -- goes through here."""
    application.setStyle("Fusion")
    application.setPalette(theme_palette())


def premium_marked_icon(icon: QIcon) -> QIcon:
    """`icon` with the premium badge in its lower right corner.

    A 22px icon has no room for the word "Premium", so it carries the same
    rounded rectangle with just "P" -- the menus spell it out (v5.28).
    """
    marked = QIcon()
    for size in icon.availableSizes() or [QSize(22, 22)]:
        source = icon.pixmap(size)
        if source.isNull():
            continue
        pixmap = QPixmap(source)
        ratio = pixmap.devicePixelRatio() or 1.0
        width = pixmap.width() / ratio
        height = pixmap.height() / ratio
        side = max(9.0, min(width, height) * 0.54)
        badge = premium_compact_badge(side)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        painter.drawPixmap(
            QRectF(width - side, height - side, side, side), badge,
            QRectF(0, 0, badge.width(), badge.height()),
        )
        painter.end()
        marked.addPixmap(pixmap)
    return marked


