def plural_category(language: str, count: int) -> str:
    """CLDR plural category of a whole number in one of the UI languages."""
    n = abs(int(count))
    if language in ("en", "es"):
        return "one" if n == 1 else "other"
    if language == "fr":
        return "one" if n in (0, 1) else "other"
    if language == "ru":
        if n % 10 == 1 and n % 100 != 11:
            return "one"
        if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
            return "few"
        return "many"
    if language == "ar":
        if n == 0:
            return "zero"
        if n == 1:
            return "one"
        if n == 2:
            return "two"
        if 3 <= n % 100 <= 10:
            return "few"
        if 11 <= n % 100 <= 99:
            return "many"
        return "other"
    return "other"


class I18N:
    """Minimal in-memory translation lookup. Keys are the original Japanese
    source strings (or {placeholder}-templated versions of f-strings)."""

    # English is the default; a saved preference (settings.json) wins.
    current: str = "en"
    # The saved preference is applied once per process. Opening a second
    # window must not drag the UI back to the stored language after the
    # user has switched it in this session.
    saved_applied: bool = False

    @staticmethod
    def t(key: str, **kwargs: Any) -> str:
        if I18N.current != "ja":
            entry = TRANSLATIONS.get(key)
            if entry is not None:
                text = entry.get(I18N.current, key)
            else:
                text = key
        else:
            text = key
        return text.format(**kwargs) if kwargs else text

    @staticmethod
    def tn(key: str, count: int) -> str:
        """The template for a message about `count` things, in the noun
        form that count needs. Format it the same way as tr()'s result."""
        if I18N.current == "ja":
            return key
        forms = PLURAL_FORMS.get(key, {}).get(I18N.current, {})
        text = forms.get(plural_category(I18N.current, count))
        return text if text is not None else I18N.t(key)


tr = I18N.t
tr_n = I18N.tn

_QT_TRANSLATORS: list[QTranslator] = []

# Key names as Microsoft writes them in each language, in Office's menus and
# on its keyboard-shortcut pages. Qt names keys in English whatever the
# language ("PgDown", "Del", "Return"), so a shortcut read "Ctrl+PgDown" in
# a Spanish menu where Office says "Ctrl+Av Pág". Arrows are drawn as arrows
# in every language, as the Japanese guide always did.
_LATIN_KEY_NAMES = {
    "Ctrl": "Ctrl", "Shift": "Shift", "Alt": "Alt", "Del": "Delete", "Esc": "Esc",
    "Return": "Enter", "Enter": "Enter", "Home": "Home", "End": "End",
    "PgUp": "Page Up", "PgDown": "Page Down", "Backspace": "Backspace", "Tab": "Tab",
    "Left": "←", "Right": "→", "Up": "↑", "Down": "↓",
}
KEY_NAMES: dict[str, dict[str, str]] = {
    "ja": _LATIN_KEY_NAMES,
    "en": _LATIN_KEY_NAMES,
    "zh_CN": _LATIN_KEY_NAMES,
    "ko": {**_LATIN_KEY_NAMES, "Backspace": "백스페이스"},
    "es": {
        **_LATIN_KEY_NAMES, "Shift": "Mayús", "Del": "Suprimir", "Return": "Entrar",
        "Enter": "Entrar", "Home": "Inicio", "End": "Fin", "PgUp": "Re Pág",
        "PgDown": "Av Pág", "Backspace": "Retroceso",
    },
    "fr": {
        **_LATIN_KEY_NAMES, "Shift": "Maj", "Del": "Suppr.", "Esc": "Échap",
        "Return": "Entrée", "Enter": "Entrée", "Home": "Origine", "PgUp": "Pg. préc",
        "PgDown": "Pg. suiv", "Backspace": "Ret. arr",
    },
    "ru": {
        **_LATIN_KEY_NAMES, "Ctrl": "CTRL", "Shift": "SHIFT", "Alt": "ALT",
        "Del": "DELETE", "Esc": "ESC", "Return": "ВВОД", "Enter": "ВВОД",
        "Home": "HOME", "End": "END", "PgUp": "PAGE UP", "PgDown": "PAGE DOWN",
        "Backspace": "BACKSPACE", "Tab": "TAB",
    },
    # Right to left, a menu reorders a shortcut that ends in a symbol:
    # "Ctrl+Shift+]" came out as "[+Ctrl+Shift". A left-to-right embedding
    # opened by the modifier keeps the whole shortcut in key order -- Qt
    # draws the action shortcuts itself, so it has to be in the names.
    "ar": {
        **_LATIN_KEY_NAMES, "Ctrl": "‪Ctrl", "Shift": "‪Shift", "Alt": "‪Alt",
    },
}


class KeyNameTranslator(QTranslator):
    """Qt's key names (its "QShortcut" context) in the UI language.

    Qt asks for these every time it writes a shortcut out -- in a menu's
    shortcut column as well as through QKeySequence.toString(NativeText).
    Every other context gets None, a null string, which sends Qt on to its
    own catalogue for the dialog buttons. An empty string would not do:
    Qt takes "" as the translation, and "Ctrl+Shift+S" came out "CTRLSHIFTS".
    """

    def __init__(self, names: dict[str, str], parent: Any = None) -> None:
        super().__init__(parent)
        self._names = names

    def translate(  # noqa: N802 - Qt's name
        self, context: str, source: str, disambiguation: Any = None, n: int = -1
    ) -> str | None:
        if context == "QShortcut" and source:
            return self._names.get(source, source)
        return None

    def isEmpty(self) -> bool:  # noqa: N802 - Qt's name
        return False


def key_sequence(keys: str) -> QKeySequence:
    """A shortcut from Qt's portable key names.

    Always portable: QKeySequence(str) reads the *translated* names, and
    once "Return" is shown as "Enter" that turns "Alt+Enter" into Alt+Return
    -- a second, identical shortcut on the same action, which Qt treats as
    ambiguous and then runs nothing.
    """
    return QKeySequence(keys, QKeySequence.PortableText)


def key_text(keys: str) -> str:
    """A key or chord written the way the UI language writes it:
    "Ctrl+Shift+S", "Ctrl+Mayús+S" in Spanish, "CTRL+SHIFT+S" in Russian.

    Takes Qt's portable names ("Ctrl+PgDown", "Del"). A chord that ends in
    a phrase rather than a key ("Shift+矢印キー") has its modifiers named
    the same way and the phrase translated; "Ctrl+1 – 9" keeps its range.
    """
    if " – " in keys:
        first, last = keys.split(" – ", 1)
        return f"{key_text(first)} – {last}"
    if keys.isascii():
        text = key_sequence(keys).toString(QKeySequence.NativeText)
        if text:
            return text
    *modifiers, last = keys.split("+")
    names = [QApplication.translate("QShortcut", name) for name in modifiers]
    return "+".join(names + [tr(last)])


